Patient Registration.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(patient_registration, "Patient Registration") {
    Component(Registration_API_Controller, "Registration API Controller", "Kubernetes container, REST API", "Handles incoming HTTP requests from the Front Desk Administrator and Patient Portal for patient admissions, intake, and demographics.")
    Component(Registration_Service, "Registration Service", "Business Logic Engine", "Processes patient registration logic and coordinates updates with downstream EMR systems.")
}

Rel(Registration_API_Controller, Registration_Service, "Invokes business logic for intake processing", "")

@enduml

Appointment Scheduling.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Appointment Scheduling", "Appointment Scheduling") {
    Component(AppointmentController, "Appointment Controller", "REST / gRPC", "Handles incoming appointment booking and viewing requests from the Patient Portal and administrative users.")
    Component(AppointmentService, "Appointment Service", "Microservice Logic", "Manages business rules for scheduling, updating, and linking appointments to medical records.")
    Component(CalendarIntegrationEngine, "Calendar Integration Engine", "mTLS / gRPC", "Synchronizes clinician schedules and links appointment entries to the EMR container.")
}

Rel(AppointmentController, AppointmentService, "Validates and routes requests")
Rel(AppointmentService, CalendarIntegrationEngine, "Links appointments to patient records")
@enduml

HL7 FHIR Interoperability.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("HL7_FHIR_Interoperability", "HL7 FHIR Interoperability") {
    Component("FHIR_API_Gateway", "FHIR API Gateway", "API Gateway / REST / mTLS", "Handles incoming and outgoing HL7 FHIR requests from external lab systems and internal services.")
    Component("Data_Ingestion_Service", "Data Ingestion Service", "gRPC / Kafka", "Processes and standardizes incoming lab and imaging results for consumption by the EMR.")
}

Rel("FHIR_API_Gateway", "Data_Ingestion_Service", "Routes validated lab and imaging payloads", "gRPC / REST via mTLS")

@enduml
